// Generate pricing request document in Google Sheets format
const data = $input.item.json;
const requirements = data.extractedRequirements?.requirements || [];

// Prepare data for Google Sheets
const rows = [];

// Header row
rows.push([
  'Category',
  'Quantity',
  'Specifications',
  'Required Features',
  'Ruckus Part Number',
  'Ruckus Unit Price',
  'Ruckus Total',
  'Extreme Part Number',
  'Extreme Unit Price',
  'Extreme Total',
  'Ubiquiti Part Number',
  'Ubiquiti Unit Price',
  'Ubiquiti Total',
  'Notes'
]);

// Data rows
requirements.forEach(req => {
  rows.push([
    req.category || '',
    req.quantity || '',
    req.specifications || '',
    (req.requiredFeatures || []).join(', '),
    '', // To be filled by Ruckus team
    '', // To be filled
    '', // Formula: quantity * unit price
    '', // To be filled
    '', // To be filled
    '', // Formula: quantity * unit price
    '', // To be filled
    '', // To be filled
    '', // Formula: quantity * unit price
    '' // Notes
  ]);
});

// Add summary rows
rows.push([]);
rows.push(['TOTALS', '', '', '', '', '', '=SUM(G2:G100)', '', '', '=SUM(J2:J100)', '', '', '=SUM(M2:M100)', '']);

return [{
  json: {
    applicationNumber: data.applicationNumber,
    applicantName: data.applicantName,
    state: data.state,
    budget: data.extractedRequirements?.budget,
    deadline: data.extractedRequirements?.deadline,
    sheetData: rows,
    requirementsData: data
  }
}];

// Generate email to Ruckus team
const data = $input.item.json;
const requirements = data.requirementsData.extractedRequirements?.requirements || [];
const sheetUrl = `https://docs.google.com/spreadsheets/d/${data.spreadsheetId}/edit`;

// Build requirements list
let reqList = '';
requirements.forEach((req, i) => {
  reqList += `${i + 1}. ${req.specifications} (Qty: ${req.quantity})\n`;
  if (req.requiredFeatures && req.requiredFeatures.length > 0) {
    reqList += `   Required: ${req.requiredFeatures.join(', ')}\n`;
  }
  reqList += `\n`;
});

const emailSubject = `E-rate Pricing Request - ${data.applicantName} (${data.applicationNumber})`;

const emailBody = `Hi Team,

I need pricing for an E-rate RFP with the following details:

Applicant: ${data.applicantName}
Application #: ${data.applicationNumber}
State: ${data.state}
Budget: $${data.budget || 'TBD'}
Deadline: ${data.deadline || 'TBD'}

REQUIREMENTS:
${reqList}

I've created a pricing sheet here:
${sheetUrl}

Please fill in:
- Part numbers
- Unit prices
- Any notes or recommendations

For both primary (Ruckus) and alternatives (Extreme, Ubiquiti) if available.

Once you've filled it out, please reply to this email and I'll generate the final proposal.

Thanks!
Kevin

---
This email was generated by the E-rate automation system.`;

return [{
  json: {
    ...data,
    sheetUrl: sheetUrl,
    emailSubject: emailSubject,
    emailBody: emailBody
  }
}];

// Save state for resumption
const data = $input.item.json;

return [{
  json: {
    success: true,
    status: 'awaiting_pricing',
    applicationNumber: data.applicationNumber,
    applicantName: data.applicantName,
    spreadsheetId: data.spreadsheetId,
    sheetUrl: data.sheetUrl,
    message: 'Pricing request sent. Waiting for manual pricing input.',
    requirementsData: data.requirementsData
  }
}];
